DO $$
DECLARE
    r RECORD;
    c RECORD;
    v_sql TEXT;
    has_null BOOLEAN;
BEGIN
    FOR r IN
        SELECT table_schema, table_name
        FROM information_schema.tables
        WHERE table_type = 'BASE TABLE'
          AND table_schema = 'public'
    LOOP
        has_null := FALSE;
        FOR c IN
            SELECT column_name
            FROM information_schema.columns
            WHERE table_schema = r.table_schema
              AND table_name = r.table_name
        LOOP
            v_sql := FORMAT(
                'SELECT 1 FROM %I.%I WHERE %I IS NULL LIMIT 1',
                r.table_schema, r.table_name, c.column_name
            );
            BEGIN
                EXECUTE v_sql;
                IF FOUND THEN
                    has_null := TRUE;
                    RAISE NOTICE 'TABEL DENGAN NILAI NULL: %.% (Kolom: %)', r.table_schema, r.table_name, c.column_name;
                END IF;
            EXCEPTION
                WHEN OTHERS THEN CONTINUE;
            END;
        END LOOP;
    END LOOP;
END $$;

CREATE OR REPLACE FUNCTION search_all(keyword TEXT)
RETURNS TABLE (
    location TEXT,
    row_data JSONB
) AS $$
DECLARE
    r RECORD;
    v_sql TEXT;
BEGIN
    FOR r IN
        SELECT table_schema, table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name NOT LIKE 'pg_%'
          AND data_type IN ('text', 'character varying', 'character', 'citext')
    LOOP
        v_sql := format(
            'SELECT %L AS location, to_jsonb(t) AS row_data
             FROM %I.%I t
             WHERE %I ILIKE %L',
            r.table_schema || '.' || r.table_name || '.' || r.column_name,
            r.table_schema, r.table_name,
            r.column_name,
            '%' || keyword || '%'
        );
        RETURN QUERY EXECUTE v_sql;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

