-- 1. Buat user database baru dengan password kuat
CREATE USER user_app WITH PASSWORD 'GantiPasswordKuat123!';

-- 2. Beri hak koneksi ke database target
GRANT ALL PRIVILEGES ON DATABASE db_utama TO user_app;

-- 3. Batasi akses koneksi ke database sensitif/lainnya
REVOKE CONNECT ON DATABASE db_prod_audit FROM user_app;

-- 4. Beri hak akses operasional pada skema public
GRANT USAGE ON SCHEMA public TO user_app;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO user_app;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO user_app;
GRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO user_app;

-- 5. Kunci default privileges agar objek baru otomatis dapat diakses user ini
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO user_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO user_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON FUNCTIONS TO user_app;

DO $$
DECLARE
    r RECORD;
    target_user TEXT := 'user_baru'; -- Ganti dengan nama user baru
BEGIN
    -- Ganti owner semua tabel
    FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO %I', r.tablename, target_user);
    END LOOP;

    -- Ganti owner semua sequence
    FOR r IN SELECT sequence_name FROM information_schema.sequences WHERE sequence_schema = 'public' LOOP
        EXECUTE format('ALTER SEQUENCE public.%I OWNER TO %I', r.sequence_name, target_user);
    END LOOP;

    -- Ganti owner semua view
    FOR r IN SELECT table_name FROM information_schema.views WHERE table_schema = 'public' LOOP
        EXECUTE format('ALTER VIEW public.%I OWNER TO %I', r.table_name, target_user);
    END LOOP;
END $$;
